method euclidianDiv(a: int,b : int) returns (q: int,r: int)
    requires a >= 0
    requires b > 0
    ensures a == b * q + r
    {
        r := a;
        q := 0;
        while (r - b >= 0)
          invariant a == b * q + r // candidate
          invariant r >= 0 // candidate
            // invariant a == b * q + r
        {
            r := r - b;
            q := q + 1;
        }

    }

method appendArray(a: array<int>, b: array<int>) returns (c: array<int>)
ensures c.Length == a.Length + b.Length
ensures forall i :: 0 <= i < a.Length ==> a[i] == c[i]
ensures forall i :: 0 <= i < b.Length ==> b[i] == c[a.Length + i]
{
	c := new int[a.Length + b.Length];

	var i := 0;
	while i < a.Length
	  invariant 0 <= i // candidate
	  invariant i <= a.Length // candidate
	  invariant c.Length == a.Length + b.Length // candidate
	  invariant forall j :: 0 <= j < i ==> a[j] == c[j] // candidate
	  invariant forall i :: 0 <= i < i ==> a[i] == c[i] // candidate
	{
		c[i] := a[i];
		i := i + 1;
	}

	while i < b.Length + a.Length
	  invariant 0 <= i // candidate
	  invariant i <= b.Length + a.Length // candidate
	  invariant c.Length == a.Length + b.Length // candidate
	  invariant forall j :: 0 <= j < a.Length ==> a[j] == c[j] // candidate
	  invariant forall j :: 0 <= j < i - a.Length ==> b[j] == c[a.Length + j] // candidate
	  invariant forall i :: 0 <= i < a.Length ==> a[i] == c[i] // candidate
	{
		c[i] := b[i - a.Length];
		i := i + 1;
	}
